+                  await route.abort("blockedbyclient");
+                  return;
+                }
+                await route.fulfill({ response });
+              },
+            }),
+          ),
+        context: () => page.context(),
+        goto: (url, options) => page.goto(url, options),
+        waitForFunction: (pageFunction, argument, options) =>
